   const validateOut = execFileSync(bin, ["validate", "--data", dataPath], {
     cwd: repo.root,
@@ -130,10 +127,10 @@ async function run(): Promise<void> {
   assert.equal(existsSync(join(outDir, "index.html")), true, "export must copy the UI");
